begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values
 ('81818181-8181-4181-8181-818181818181','recovery-a@example.test'),
 ('82828282-8282-4282-8282-828282828282','recovery-b@example.test');
select ok(not has_function_privilege('anon','public.restore_project(uuid,uuid,bigint)','EXECUTE'),'anonymous cannot restore project');
select ok(not has_function_privilege('anon','public.restore_project_part(uuid,uuid,uuid,bigint)','EXECUTE'),'anonymous cannot restore part');
select ok(not has_function_privilege('anon','public.get_deleted_projects()','EXECUTE'),'anonymous cannot list deleted projects');
select ok(not has_table_privilege('authenticated','public.project_recovery_commands','INSERT'),'recovery receipts not client writable');
select ok(not has_table_privilege('authenticated','public.counter_events','INSERT'),'events remain RPC only');
set local role authenticated;
set local request.jwt.claim.sub='81818181-8181-4181-8181-818181818181';
select set_config('test.rec_project',public.create_project('81818181-0000-4000-8000-000000000001','복구 가디건','메모')::text,true);
select set_config('test.rec_part',public.apply_project_part_command((current_setting('test.rec_project')::jsonb->>'id')::uuid,'81818181-0000-4000-8000-000000000002',0,'{"type":"create","name":"소매"}'::jsonb)::text,true);
select is(public.apply_counter_command('81818181-0000-4000-8000-000000000003',(current_setting('test.rec_project')::jsonb->>'workItemId')::uuid,0,now(),'recovery-test','{"type":"change","counter":"stitch","delta":1}')->>'status','applied','default counter changed before deletion');
select is(public.apply_counter_command('81818181-0000-4000-8000-000000000004',(current_setting('test.rec_part')::jsonb->>'workItemId')::uuid,0,now(),'recovery-test','{"type":"completeRow","stitch":"keep"}')->>'status','applied','part counter changed before deletion');
select set_config('test.rec_event',(select id::text from public.counter_events where work_item_id=(current_setting('test.rec_part')::jsonb->>'workItemId')::uuid),true);
select is(public.apply_project_part_command((current_setting('test.rec_project')::jsonb->>'id')::uuid,'81818181-0000-4000-8000-000000000005',1,jsonb_build_object('type','delete','partId',current_setting('test.rec_part')::jsonb->>'partId'))->>'status','applied','part individually deleted');
select is(public.get_deleted_project_parts((current_setting('test.rec_project')::jsonb->>'id')::uuid)->'items'->0->>'id',current_setting('test.rec_part')::jsonb->>'partId','deleted part listed by owner');
select is((public.get_deleted_project_parts((current_setting('test.rec_project')::jsonb->>'id')::uuid)->'items'->0->>'eventCount')::bigint,1::bigint,'deleted part history summary preserved');
select is((public.get_deleted_project_parts((current_setting('test.rec_project')::jsonb->>'id')::uuid)->'items'->0->>'row')::bigint,1::bigint,'deleted part counter summary preserved');
select is(public.update_project((current_setting('test.rec_project')::jsonb->>'id')::uuid,2,'복구 가디건','메모','paused')->>'status','paused','pre-delete status paused');
select is(public.delete_project((current_setting('test.rec_project')::jsonb->>'id')::uuid,3)->>'result','deleted','project deleted');
select is(public.get_deleted_projects()->0->>'id',current_setting('test.rec_project')::jsonb->>'id','deleted project listed by owner');
select is((select count(*) from public.projects),0::bigint,'ordinary project RLS still hides deleted project');
select is((select count(*) from public.counters),0::bigint,'ordinary counter RLS still hides all deleted project counters');
select throws_ok(format('select public.restore_project_part(%L::uuid,%L::uuid,%L::uuid,4)',current_setting('test.rec_project')::jsonb->>'id',current_setting('test.rec_part')::jsonb->>'partId','81818181-0000-4000-8000-000000000006'),'22023',null,'part cannot be restored inside deleted project');
set local request.jwt.claim.sub='82828282-8282-4282-8282-828282828282';
select is(jsonb_array_length(public.get_deleted_projects()),0,'other user cannot list deleted projects');
select throws_ok(format('select public.get_deleted_project_parts(%L::uuid)',current_setting('test.rec_project')::jsonb->>'id'),'P0002',null,'other user cannot list deleted parts');
select throws_ok(format('select public.restore_project(%L::uuid,%L::uuid,4)',current_setting('test.rec_project')::jsonb->>'id','82828282-0000-4000-8000-000000000001'),'P0002',null,'other user cannot restore project');
set local request.jwt.claim.sub='81818181-8181-4181-8181-818181818181';
select is(public.restore_project((current_setting('test.rec_project')::jsonb->>'id')::uuid,'81818181-0000-4000-8000-000000000007',3)->>'status','conflict','stale recovery revision rejected');
select is(public.restore_project((current_setting('test.rec_project')::jsonb->>'id')::uuid,'81818181-0000-4000-8000-000000000008',4)->>'status','restored','project restored');
select is(public.restore_project((current_setting('test.rec_project')::jsonb->>'id')::uuid,'81818181-0000-4000-8000-000000000008',4)->>'status','duplicate','lost response retry is idempotent');
select throws_ok(format('select public.restore_project(%L::uuid,%L::uuid,5)',current_setting('test.rec_project')::jsonb->>'id','81818181-0000-4000-8000-000000000008'),'22023',null,'same recovery ID cannot change payload');
select is((select status from public.projects where id=(current_setting('test.rec_project')::jsonb->>'id')::uuid),'paused','project restored with original paused status');
select is((select revision from public.projects where id=(current_setting('test.rec_project')::jsonb->>'id')::uuid),5::bigint,'project revision advances exactly once');
select is((select count(*) from public.project_parts),1::bigint,'individually deleted part stays deleted');
select is((select current_value from public.counters where work_item_id=(current_setting('test.rec_project')::jsonb->>'workItemId')::uuid and counter_type='stitch'),1::bigint,'default count preserved');
select is((select recovery_revision from public.work_items where id=(current_setting('test.rec_project')::jsonb->>'workItemId')::uuid),1::bigint,'recovery boundary recorded without rewriting count revision');
select is((select revision from public.work_items where id=(current_setting('test.rec_project')::jsonb->>'workItemId')::uuid),1::bigint,'counter revision unchanged by recovery');
select is(public.update_project((current_setting('test.rec_project')::jsonb->>'id')::uuid,5,'복구 가디건','메모','active')->>'status','active','restored project can resume');
select is(public.restore_project_part((current_setting('test.rec_project')::jsonb->>'id')::uuid,(current_setting('test.rec_part')::jsonb->>'partId')::uuid,'81818181-0000-4000-8000-000000000009',6)->>'status','restored','part restored');
select is(public.restore_project_part((current_setting('test.rec_project')::jsonb->>'id')::uuid,(current_setting('test.rec_part')::jsonb->>'partId')::uuid,'81818181-0000-4000-8000-000000000009',6)->>'status','duplicate','part restore retry idempotent');
select is((select work_item_id::text from public.project_parts where id=(current_setting('test.rec_part')::jsonb->>'partId')::uuid),current_setting('test.rec_part')::jsonb->>'workItemId','part and work item IDs preserved');
select is((select position from public.project_parts where id=(current_setting('test.rec_part')::jsonb->>'partId')::uuid),2::bigint,'restored part appended with unique position');
select is((select current_value from public.counters where work_item_id=(current_setting('test.rec_part')::jsonb->>'workItemId')::uuid and counter_type='row'),1::bigint,'part row count preserved');
select is((select id::text from public.counter_events where work_item_id=(current_setting('test.rec_part')::jsonb->>'workItemId')::uuid),current_setting('test.rec_event'),'original event ID preserved');
select is(public.apply_counter_command('81818181-0000-4000-8000-000000000010',(current_setting('test.rec_part')::jsonb->>'workItemId')::uuid,1,now(),'recovery-test','{"type":"change","counter":"stitch","delta":1}')->>'status','applied','normal counting after restore works');
select is(public.apply_counter_command('81818181-0000-4000-8000-000000000011',(current_setting('test.rec_part')::jsonb->>'workItemId')::uuid,1,now(),'recovery-test','{"type":"change","counter":"stitch","delta":1}')->>'status','conflict','old pending revision not rebased by recovery');
set local request.jwt.claim.sub='82828282-8282-4282-8282-828282828282';
select throws_ok(format('select public.restore_project_part(%L::uuid,%L::uuid,%L::uuid,7)',current_setting('test.rec_project')::jsonb->>'id',current_setting('test.rec_part')::jsonb->>'partId','82828282-0000-4000-8000-000000000002'),'P0002',null,'other user cannot restore part');
set local request.jwt.claim.sub='';
select throws_ok(format('select public.restore_project(%L::uuid,%L::uuid,7)',current_setting('test.rec_project')::jsonb->>'id','81818181-0000-4000-8000-000000000012'),'28000',null,'missing auth rejected inside restore RPC');
select * from finish();
rollback;
